```python
class Relation:
    def __init__(self, pairs):
        self.pairs = pairs

    def is_reflexive(self):
        for a in self.pairs:
            if (a, a) not in self.pairs:
                return False
        return True

relation = Relation([(1, 1), (2, 2), (1, 2)])
print(relation.is_reflexive())
``` 

